export const GENERATED_BLOCK_NAMES = Object.keys(BLOCKS);

export function hasGeneratedBlockPreview(name: string): boolean {
  return Object.hasOwn(BLOCKS, name);
}

export function GeneratedBlockPreview({ name }: { name: string }) {
  const Block = BLOCKS[name];
  if (!Block) return null;
  return (
    <React.Suspense fallback={<p className="text-sm text-muted-foreground">Loading preview…</p>}>
      <Block />
    </React.Suspense>
  );
}
